1	package events
2	
3	import (
4		"database/sql"
5		"encoding/json"
6		"errors"
7		"sync"
8	
9		"github.com/alicegogogogogo/local-first-sync-service/internal/store"
10	)
11	
12	// Gate is the only seam the change event service uses to reach the
13	// registration and permission layers. It is evaluated inside the caller's
14	// serialized transaction, so a rejected request never observes change
15	// content and the gate and the gated write commit as one judgment.
16	type Gate interface {
17		// DeviceAuthorizedTx returns nil when deviceID is registered and currently
18		// authorized for documentID, store.ErrDeviceNotFound when the device is not
19		// registered and ErrPermissionDenied when its access was revoked.
20		DeviceAuthorizedTx(tx *sql.Tx, documentID, deviceID string) error
21	}
22	
23	// Service is the change event service: the durable change log, snapshots and
24	// restores plus the in-memory long-poll and subscription observers of them.
25	type Service struct {
26		db   *sql.DB
27		gate Gate
28	
29		// mu guards waits, subs, nextWaitID, nextSubID and closed. Parked long
30		// polls wait on a per-document set of channels; a committed change closes
31		// (signals) every channel parked on it. WebSocket subscriptions live in a
32		// second registry keyed by (document, device): a commit signals every
33		// subscription under the document, while the permission service signals
34		// only the matching device's subscriptions.
35		mu       sync.Mutex
36		waits    map[string]map[uint64]chan struct{}
37		subs     map[subKey]map[uint64]*subscription
38		nextWait uint64
39		nextSub  uint64
40		subWG    sync.WaitGroup
41		closed   bool
42	}
43	
44	// New constructs the change event service over the shared kernel handle and
45	// creates its tables. gate answers the registration/permission checks inside
46	// a write transaction; it may be nil for callers that only use the paths that
47	// do not gate (ordinary post, merge, snapshots, reads).
48	func New(kernel *store.Store, gate Gate) (*Service, error) {
49		db := kernel.DB()
50		if _, err := db.Exec(schema); err != nil {
51			return nil, err
52		}
53		return &Service{
54			db:    db,
55			gate:  gate,
56			waits: make(map[string]map[uint64]chan struct{}),
57			subs:  make(map[subKey]map[uint64]*subscription),
58		}, nil
59	}
60	
61	// PostChanges validates and commits one batch atomically.
62	//
63	// Every change must have a non-empty id; duplicate ids within the batch are
64	// rejected by the caller before reaching this point. On conflict the returned
65	// error is *ErrConflict and nothing is written. Cursors are assigned in batch
66	// order to ids that do not yet exist. Results are returned in the same order
67	// as the input.
68	func (s *Service) PostChanges(documentID string, changes []Change) ([]Result, error) {
69		tx, err := s.db.Begin()
70		if err != nil {
71			return nil, err
72		}
73		defer func() { _ = tx.Rollback() }()
74	
75		results, pending, err := resolveChanges(tx, documentID, changes)
76		if err != nil {
77			return nil, err
78		}
79		if err := appendPending(tx, documentID, changes, pending, results); err != nil {
80			return nil, err
81		}
82	
83		if err := tx.Commit(); err != nil {
84			return nil, err
85		}
86		if len(pending) > 0 {
87			s.notifyWaiters(documentID)
88		}
89		return results, nil
90	}
91	
92	// ReplayChanges commits a retried offline batch with exactly the same change
93	// semantics as PostChanges, but enforces the gate (registration then
94	// permission) first in the same transaction: an unregistered device yields
95	// store.ErrDeviceNotFound (404) and a revoked device yields
96	// ErrPermissionDenied (403). None of those outcomes writes anything or
97	// exposes change content.
98	func (s *Service) ReplayChanges(documentID string, changes []Change) ([]Result, error) {
99		tx, err := s.db.Begin()
100		if err != nil {
101			return nil, err
102		}
103		defer func() { _ = tx.Rollback() }()
104	
105		// Gate first: the device row and the permission row are read before any
106		// change id is resolved, so a rejected replay cannot reveal content.
107		if s.gate != nil {
108			if err := s.gate.DeviceAuthorizedTx(tx, documentID, changes[0].DeviceID); err != nil {
109				return nil, err
110			}
111		}
112	
113		results, pending, err := resolveChanges(tx, documentID, changes)
114		if err != nil {
115			return nil, err
116		}
117		if err := appendPending(tx, documentID, changes, pending, results); err != nil {
118			return nil, err
119		}
120	
121		if err := tx.Commit(); err != nil {
122			return nil, err
123		}
124		if len(pending) > 0 {
125			s.notifyWaiters(documentID)
126		}
127		return results, nil
128	}
129	
130	// resolveChanges resolves every change id against existing rows inside tx,
131	// falling back to the retained summaries of compacted-away ids. A single
132	// device/payload mismatch aborts the whole batch before any cursor is
133	// allocated. It returns the per-id results and the indices of genuinely new
134	// changes that still need a cursor.
135	func resolveChanges(tx *sql.Tx, documentID string, changes []Change) ([]Result, []int, error) {
136		results := make([]Result, len(changes))
137		pending := make([]int, 0, len(changes))
138		for i, c := range changes {
139			var existingDevice string
140			var existingPayload []byte
141			var existingCursor int64
142			err := tx.QueryRow(
143				`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
144				documentID, c.ID,
145			).Scan(&existingCursor, &existingDevice, &existingPayload)
146			switch {
147			case errors.Is(err, sql.ErrNoRows):
148				// No online row: the id may belong to a change compaction
149				// trimmed, whose retained summary still decides idempotency.
150				found, cursor, err := resolveTrimmedIdentity(tx, documentID, c)
151				if err != nil {
152					return nil, nil, err
153				}
154				if !found {
155					pending = append(pending, i)
156					continue
157				}
158				results[i] = Result{
159					ID:      c.ID,
160					Created: false,
161					Cursor:  cursor,
162				}
163			case err != nil:
164				return nil, nil, err
165			default:
166				if existingDevice != c.DeviceID || !store.JSONEqual(existingPayload, c.Payload) {
167					return nil, nil, &ErrConflict{ID: c.ID}
168				}
169				results[i] = Result{
170					ID:      c.ID,
171					Created: false,
172					Cursor:  existingCursor,
173				}
174			}
175		}
176		return results, pending, nil
177	}
178	
179	// appendPending allocates contiguous cursors to the new change indices and
180	// inserts them in input order. It runs inside the caller's transaction. The
181	// allocation continues past the compaction boundary, so trimming the online
182	// log never makes the cursor space restart.
183	func appendPending(tx *sql.Tx, documentID string, changes []Change, pending []int, results []Result) error {
184		nextCursor, err := currentCursorTx(tx, documentID)
185		if err != nil {
186			return err
187		}
188		nextCursor++
189		for _, i := range pending {
190			c := changes[i]
191			if _, err := tx.Exec(
192				`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
193				documentID, nextCursor, c.ID, c.DeviceID, []byte(c.Payload),
194			); err != nil {
195				return err
196			}
197			results[i] = Result{
198				ID:      c.ID,
199				Created: true,
200				Cursor:  nextCursor,
201			}
202			nextCursor++
203		}
204		return nil
205	}
206	
207	// MergeChange validates and appends one change against a caller-observed base
208	// cursor, all within a single serialized transaction.
209	//
210	//   - An existing id is idempotent only when deviceId and the decoded payload
211	//     match (Outcome "idempotent", with the original Result); a mismatch is an
212	//     *ErrConflict and nothing is written.
213	//   - A new id with baseCursor equal to the current cursor is appended as
214	//     "applied".
215	//   - A new id with a base cursor behind the current one is appended as
216	//     "merged" only when every change after baseCursor carries a JSON object
217	//     payload whose top-level keys are disjoint from the new payload's; any
218	//     non-object later payload or shared key is an *ErrConflict.
219	//
220	// A non-zero baseCursor for an unknown document, or a baseCursor greater than
221	// the current cursor, returns ErrStaleCursor. A baseCursor below the
222	// compaction boundary returns ErrCompactedBase: the changes the merge would be
223	// checked against have left the online log, so the conflict check cannot be
224	// completed. An unknown document with baseCursor 0 accepts the first change as
225	// "applied".
226	func (s *Service) MergeChange(documentID string, baseCursor int64, c Change) (MergeResult, error) {
227		tx, err := s.db.Begin()
228		if err != nil {
229			return MergeResult{}, err
230		}
231		defer func() { _ = tx.Rollback() }()
232	
233		// Current cursor is the document's high-water mark (0 when unknown); it
234		// never drops below the compaction boundary.
235		current, err := currentCursorTx(tx, documentID)
236		if err != nil {
237			return MergeResult{}, err
238		}
239		if baseCursor > current || (baseCursor != 0 && current == 0) {
240			return MergeResult{}, ErrStaleCursor
241		}
242		boundary, err := boundaryOfTx(tx, documentID)
243		if err != nil {
244			return MergeResult{}, err
245		}
246		if baseCursor < boundary {
247			return MergeResult{}, ErrCompactedBase
248		}
249	
250		// An existing id keeps the original idempotency/conflict rules.
251		var existingDevice string
252		var existingPayload []byte
253		var existingCursor int64
254		err = tx.QueryRow(
255			`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
256			documentID, c.ID,
257		).Scan(&existingCursor, &existingDevice, &existingPayload)
258		switch {
259		case errors.Is(err, sql.ErrNoRows):
260			// No online row: a compacted-away id still answers from its retained
261			// summary; anything else is a new id and falls through to the append
262			// logic below.
263			found, cursor, err := resolveTrimmedIdentity(tx, documentID, c)
264			if err != nil {
265				return MergeResult{}, err
266			}
267			if found {
268				return MergeResult{
269					ID:      c.ID,
270					Outcome: "idempotent",
271					Cursor:  cursor,
272					Result: &Result{
273						ID:      c.ID,
274						Created: false,
275						Cursor:  cursor,
276					},
277				}, nil
278			}
279		case err != nil:
280			return MergeResult{}, err
281		default:
282			if existingDevice != c.DeviceID || !store.JSONEqual(existingPayload, c.Payload) {
283				return MergeResult{}, &ErrConflict{ID: c.ID}
284			}
285			return MergeResult{
286				ID:      c.ID,
287				Outcome: "idempotent",
288				Cursor:  existingCursor,
289				Result: &Result{
290					ID:      c.ID,
291					Created: false,
292					Cursor:  existingCursor,
293				},
294			}, nil
295		}
