297		outcome := "applied"
298		if baseCursor < current {
299			// Merge is allowed only when every change after baseCursor is a JSON
300			// object whose top-level keys do not collide with the new payload's.
301			newKeys, err := objectKeys(c.Payload)
302			if err != nil {
