346		next := current + 1
347		if _, err := tx.Exec(
348			`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
349			documentID, next, c.ID, c.DeviceID, []byte(c.Payload),
350		); err != nil {
