package events

import (
	"database/sql"
	"encoding/json"
	"errors"
	"sync"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// Gate is the only seam the change event service uses to reach the
// registration and permission layers. It is evaluated inside the caller's
// serialized transaction, so a rejected request never observes change
// content and the gate and the gated write commit as one judgment.
type Gate interface {
	// DeviceAuthorizedTx returns nil when deviceID is registered and currently
	// authorized for documentID, store.ErrDeviceNotFound when the device is not
	// registered and ErrPermissionDenied when its access was revoked.
	DeviceAuthorizedTx(tx *sql.Tx, documentID, deviceID string) error
}

// Service is the change event service: the durable change log, snapshots and
// restores plus the in-memory long-poll and subscription observers of them.
type Service struct {
	db   *sql.DB
	gate Gate

	// mu guards waits, subs, nextWaitID, nextSubID and closed. Parked long
	// polls wait on a per-document set of channels; a committed change closes
	// (signals) every channel parked on it. WebSocket subscriptions live in a
	// second registry keyed by (document, device): a commit signals every
	// subscription under the document, while the permission service signals
	// only the matching device's subscriptions.
	mu       sync.Mutex
	waits    map[string]map[uint64]chan struct{}
	subs     map[subKey]map[uint64]*subscription
	nextWait uint64
	nextSub  uint64
	subWG    sync.WaitGroup
	closed   bool
}

// New constructs the change event service over the shared kernel handle and
// creates its tables. gate answers the registration/permission checks inside
// a write transaction; it may be nil for callers that only use the paths that
// do not gate (ordinary post, merge, snapshots, reads).
func New(kernel *store.Store, gate Gate) (*Service, error) {
	db := kernel.DB()
	if _, err := db.Exec(schema); err != nil {
		return nil, err
	}
	return &Service{
		db:    db,
		gate:  gate,
		waits: make(map[string]map[uint64]chan struct{}),
		subs:  make(map[subKey]map[uint64]*subscription),
	}, nil
}

// PostChanges validates and commits one batch atomically.
//
// Every change must have a non-empty id; duplicate ids within the batch are
// rejected by the caller before reaching this point. On conflict the returned
// error is *ErrConflict and nothing is written. Cursors are assigned in batch
// order to ids that do not yet exist. Results are returned in the same order
// as the input.
func (s *Service) PostChanges(documentID string, changes []Change) ([]Result, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	results, pending, err := resolveChanges(tx, documentID, changes)
	if err != nil {
		return nil, err
	}
	if err := appendPending(tx, documentID, changes, pending, results); err != nil {
		return nil, err
	}

	if err := tx.Commit(); err != nil {
		return nil, err
	}
	if len(pending) > 0 {
		s.notifyWaiters(documentID)
	}
	return results, nil
}

// ReplayChanges commits a retried offline batch with exactly the same change
// semantics as PostChanges, but enforces the gate (registration then
// permission) first in the same transaction: an unregistered device yields
// store.ErrDeviceNotFound (404) and a revoked device yields
// ErrPermissionDenied (403). None of those outcomes writes anything or
// exposes change content.
func (s *Service) ReplayChanges(documentID string, changes []Change) ([]Result, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	// Gate first: the device row and the permission row are read before any
	// change id is resolved, so a rejected replay cannot reveal content.
	if s.gate != nil {
		if err := s.gate.DeviceAuthorizedTx(tx, documentID, changes[0].DeviceID); err != nil {
			return nil, err
		}
	}

	results, pending, err := resolveChanges(tx, documentID, changes)
	if err != nil {
		return nil, err
	}
	if err := appendPending(tx, documentID, changes, pending, results); err != nil {
		return nil, err
	}

	if err := tx.Commit(); err != nil {
		return nil, err
	}
	if len(pending) > 0 {
		s.notifyWaiters(documentID)
	}
	return results, nil
}

// resolveChanges resolves every change id against existing rows inside tx,
// falling back to the retained summaries of compacted-away ids. A single
// device/payload mismatch aborts the whole batch before any cursor is
// allocated. It returns the per-id results and the indices of genuinely new
// changes that still need a cursor.
func resolveChanges(tx *sql.Tx, documentID string, changes []Change) ([]Result, []int, error) {
	results := make([]Result, len(changes))
	pending := make([]int, 0, len(changes))
	for i, c := range changes {
		var existingDevice string
		var existingPayload []byte
		var existingCursor int64
		err := tx.QueryRow(
			`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
			documentID, c.ID,
		).Scan(&existingCursor, &existingDevice, &existingPayload)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			// No online row: the id may belong to a change compaction
			// trimmed, whose retained summary still decides idempotency.
			found, cursor, err := resolveTrimmedIdentity(tx, documentID, c)
			if err != nil {
				return nil, nil, err
			}
			if !found {
				pending = append(pending, i)
				continue
			}
			results[i] = Result{
				ID:      c.ID,
				Created: false,
				Cursor:  cursor,
			}
		case err != nil:
			return nil, nil, err
		default:
			if existingDevice != c.DeviceID || !store.JSONEqual(existingPayload, c.Payload) {
				return nil, nil, &ErrConflict{ID: c.ID}
			}
			results[i] = Result{
				ID:      c.ID,
				Created: false,
				Cursor:  existingCursor,
			}
		}
	}
	return results, pending, nil
}

// appendPending allocates contiguous cursors to the new change indices and
// inserts them in input order. It runs inside the caller's transaction. The
// allocation continues past the compaction boundary, so trimming the online
// log never makes the cursor space restart.
func appendPending(tx *sql.Tx, documentID string, changes []Change, pending []int, results []Result) error {
	nextCursor, err := currentCursorTx(tx, documentID)
	if err != nil {
		return err
	}
	nextCursor++
	for _, i := range pending {
		c := changes[i]
		if _, err := tx.Exec(
			`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
			documentID, nextCursor, c.ID, c.DeviceID, []byte(c.Payload),
		); err != nil {
			return err
		}
		results[i] = Result{
			ID:      c.ID,
			Created: true,
			Cursor:  nextCursor,
		}
		nextCursor++
	}
	return nil
}

// MergeChange validates and appends one change against a caller-observed base
// cursor, all within a single serialized transaction.
//
//   - An existing id is idempotent only when deviceId and the decoded payload
//     match (Outcome "idempotent", with the original Result); a mismatch is an
//     *ErrConflict and nothing is written.
//   - A new id with baseCursor equal to the current cursor is appended as
//     "applied".
//   - A new id with a base cursor behind the current one is appended as
//     "merged" only when every change after baseCursor carries a JSON object
//     payload whose top-level keys are disjoint from the new payload's; any
//     non-object later payload or shared key is an *ErrConflict.
//
// A non-zero baseCursor for an unknown document, or a baseCursor greater than
// the current cursor, returns ErrStaleCursor. A baseCursor below the
// compaction boundary returns ErrCompactedBase: the changes the merge would be
// checked against have left the online log, so the conflict check cannot be
// completed. An unknown document with baseCursor 0 accepts the first change as
// "applied".
func (s *Service) MergeChange(documentID string, baseCursor int64, c Change) (MergeResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return MergeResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	// Current cursor is the document's high-water mark (0 when unknown); it
	// never drops below the compaction boundary.
	current, err := currentCursorTx(tx, documentID)
	if err != nil {
		return MergeResult{}, err
	}
	if baseCursor > current || (baseCursor != 0 && current == 0) {
		return MergeResult{}, ErrStaleCursor
	}
	boundary, err := boundaryOfTx(tx, documentID)
	if err != nil {
		return MergeResult{}, err
	}
	if baseCursor < boundary {
		return MergeResult{}, ErrCompactedBase
	}

	// An existing id keeps the original idempotency/conflict rules.
	var existingDevice string
	var existingPayload []byte
	var existingCursor int64
	err = tx.QueryRow(
		`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
		documentID, c.ID,
	).Scan(&existingCursor, &existingDevice, &existingPayload)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No online row: a compacted-away id still answers from its retained
		// summary; anything else is a new id and falls through to the append
		// logic below.
		found, cursor, err := resolveTrimmedIdentity(tx, documentID, c)
		if err != nil {
			return MergeResult{}, err
		}
		if found {
			return MergeResult{
				ID:      c.ID,
				Outcome: "idempotent",
				Cursor:  cursor,
				Result: &Result{
					ID:      c.ID,
					Created: false,
					Cursor:  cursor,
				},
			}, nil
		}
	case err != nil:
		return MergeResult{}, err
	default:
		if existingDevice != c.DeviceID || !store.JSONEqual(existingPayload, c.Payload) {
			return MergeResult{}, &ErrConflict{ID: c.ID}
		}
		return MergeResult{
			ID:      c.ID,
			Outcome: "idempotent",
			Cursor:  existingCursor,
			Result: &Result{
				ID:      c.ID,
				Created: false,
				Cursor:  existingCursor,
			},
		}, nil
	}

	outcome := "applied"
	if baseCursor < current {
		// Merge is allowed only when every change after baseCursor is a JSON
		// object whose top-level keys do not collide with the new payload's.
		newKeys, err := objectKeys(c.Payload)
		if err != nil {
			if errors.Is(err, errNotObject) {
				return MergeResult{}, &ErrConflict{ID: c.ID}
			}
			return MergeResult{}, err
		}
		rows, err := tx.Query(
			`SELECT payload FROM changes
			 WHERE document_id = ? AND cursor > ?
			 ORDER BY cursor ASC`,
			documentID, baseCursor,
		)
		if err != nil {
			return MergeResult{}, err
		}
		for rows.Next() {
			var laterPayload []byte
			if err := rows.Scan(&laterPayload); err != nil {
				_ = rows.Close()
				return MergeResult{}, err
			}
			laterKeys, err := objectKeys(laterPayload)
			if err != nil {
				_ = rows.Close()
				if errors.Is(err, errNotObject) {
					return MergeResult{}, &ErrConflict{ID: c.ID}
				}
				return MergeResult{}, err
			}
			for k := range newKeys {
				if _, clash := laterKeys[k]; clash {
					_ = rows.Close()
					return MergeResult{}, &ErrConflict{ID: c.ID}
				}
			}
		}
		if err := rows.Err(); err != nil {
			_ = rows.Close()
			return MergeResult{}, err
		}
		_ = rows.Close()
		outcome = "merged"
	}

	next := current + 1
	if _, err := tx.Exec(
		`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
		documentID, next, c.ID, c.DeviceID, []byte(c.Payload),
	); err != nil {
		return MergeResult{}, err
	}

	if err := tx.Commit(); err != nil {
		return MergeResult{}, err
	}
	s.notifyWaiters(documentID)
	return MergeResult{ID: c.ID, Outcome: outcome, Cursor: next}, nil
}

// errNotObject marks a payload that is not a JSON object.
var errNotObject = errors.New("payload is not a JSON object")

// objectKeys returns the top-level keys of a JSON object payload. A null,
// array or scalar payload yields errNotObject.
func objectKeys(raw json.RawMessage) (map[string]struct{}, error) {
	var m map[string]json.RawMessage
	if err := json.Unmarshal(raw, &m); err != nil {
		// Valid JSON that is not an object (array, scalar, null) decodes with
		// a type error into a map; treat it and malformed JSON as non-object.
		return nil, errNotObject
	}
	if m == nil {
		return nil, errNotObject
	}
	keys := make(map[string]struct{}, len(m))
	for k := range m {
		keys[k] = struct{}{}
	}
	return keys, nil
}

package server

import (
	"errors"
	"net/http"
	"net/url"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/events"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// changeExportResponse is the export body with the top-level key order fixed
// to changes then count. Changes is always a non-nil slice so an empty
// export serializes as [] rather than null. Each element is an
// events.ListedChange, whose key order is id, deviceId, payload, cursor — the
// same record the paged read emits.
type changeExportResponse struct {
	Changes []events.ListedChange `json:"changes"`
	Count   int                   `json:"count"`
}

// exportRequested reports whether the query carries the export's from/to
// parameters. A present key counts even with an empty value (?from= is the
// export with the default bound), matching the document-level collection.
func exportRequested(q url.Values) bool {
	if _, ok := q["from"]; ok {
		return true
	}
	_, ok := q["to"]
	return ok
}

// parseExportInterval parses the shared from/to export parameters, writing
// the documented 400 on an illegal value. from defaults to 0; a nil to means
// the interval has no upper bound; to below from is rejected. It is shared by
// the document-scoped and session-scoped exports so their query semantics
// cannot drift apart.
func parseExportInterval(w http.ResponseWriter, q url.Values) (from int64, to *int64, ok bool) {
	from = 0
	if raw := q.Get("from"); raw != "" {
		v, valid := parseCursorPath(raw)
		if !valid {
			writeError(w, http.StatusBadRequest, "from must be a non-negative integer")
			return 0, nil, false
		}
		from = v
	}

	if raw := q.Get("to"); raw != "" {
		v, valid := parseCursorPath(raw)
		if !valid {
			writeError(w, http.StatusBadRequest, "to must be a non-negative integer")
			return 0, nil, false
		}
		to = &v
	}
	if to != nil && *to < from {
		writeError(w, http.StatusBadRequest, "to must not be less than from")
		return 0, nil, false
	}
	return from, to, true
}

// writeChangeExport renders an export result in the shared response shape: a
// single compact JSON line with the changes,count key order, an empty export
// serializing as [] with count 0.
func writeChangeExport(w http.ResponseWriter, rows []events.ListedChange) {
	if rows == nil {
		rows = make([]events.ListedChange, 0)
	}
	writeJSON(w, http.StatusOK, changeExportResponse{Changes: rows, Count: len(rows)})
}

// handleExportChanges is the read-only batch export over a document's change
// collection:
//
//	GET /v1/documents/{documentID}/changes?from=0&to=N
//
// from defaults to 0; to absent means no upper bound. Only changes whose
// cursor is in the closed [from, to] interval and still in the online log are
// returned, in ascending cursor order, at most one entry per cursor. An
// unknown document or a range without any online change — including one that
// lies entirely inside the trimmed region — is a successful 200 with an empty
// list and count 0, not an error. Changes compacted out of the online log
// never appear. The handler writes nothing: it creates no change, moves no
// cursor, records no change and notifies the push channels.
func handleExportChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	from, to, ok := parseExportInterval(w, r.URL.Query())
	if !ok {
		return
	}

	rows, err := s.ExportChanges(documentID, from, to)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to export changes")
		return
	}
	writeChangeExport(w, rows)
}

// handleSessionExportChanges is the session-scoped view of the change-log
// batch export, sharing the session change read's exact collection path:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/changes?from=0&to=N
//
// The interval semantics and the response body are identical to the
// document-level export; around them sit the session view's checks in their
// fixed order — request shape and parameters (400), session existence (404),
// the session device's document permission (403) — so a rejected export
// exposes no change content and writes nothing.
func handleSessionExportChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// Malformed interval parameters are a request-shape error (400) checked
	// before the resource lookup (404), matching the paged read's ordering.
	from, to, ok := parseExportInterval(w, r.URL.Query())
	if !ok {
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}

	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	rows, err := s.ExportChanges(documentID, from, to)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to export changes")
		return
	}
	writeChangeExport(w, rows)
}

// malformedChangeExportPath reports whether p targets the change-log
// collection's export shape but is not the collection's exact location
// (/v1/documents/{documentID}/changes): a trailing slash (an empty trailing
// segment) or extra path segments past the collection. The paged read and
// this export share that exact collection path; its terminal subresources
// (poll, compact, subscribe under the session family) have their own keyword
// guards, so only a genuinely unrecognized suffix reaches this check.
// ServeMux would answer it with a redirect or a plain-text 404/405; the
// change surface promises a JSON error and never a redirect. Empty segments
// are already rejected by the guard itself. The keyword is matched only past
// the documentID position, so a document literally named "changes" keeps its
// ordinary routes.
func malformedChangeExportPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	for i, seg := range segs {
		if seg != "changes" || i == 0 {
			continue
		}
		// Keyword position reached. The collection is exactly
		// {documentID}/changes; the poll and compact subresources are their own
		// endpoints and keep their own guards. Anything else (a trailing slash,
		// an unrecognized extra segment) is a malformed 400.
		if i == 1 {
			collection := len(segs) == 2 && segs[0] != ""
			knownSubresource := len(segs) >= 3 && (segs[2] == "poll" || segs[2] == "compact")
			return !(collection || knownSubresource)
		}
		return false
	}
	return false
}

// malformedSessionChangesPath reports whether p targets the session-scoped
// change collection's shape but is not the collection's exact location
// (/v1/sessions/{sessionId}/documents/{documentId}/changes): extra path
// segments past the collection. The paged read and the interval export share
// that exact collection path; the subscribe subresource has its own endpoint
// and keyword guard, so only a genuinely unrecognized suffix reaches this
// check. ServeMux would answer it with a plain-text 404; the change surface
// promises a JSON 400 and never a redirect. Empty segments (doubled slashes,
// a trailing slash) are already rejected by the guard itself.
//
// "changes" is treated as the collection keyword only in the fourth segment,
// right after the document identifier; a session or document identifier
// literally named "changes" occupies an identifier position and keeps its
// ordinary routes.
func malformedSessionChangesPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/sessions/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	// The CRDT namespace ("crdt" immediately past the document identifier)
	// has its own guard; "changes" there is an ordinary identifier, not this
	// collection's keyword.
	if len(segs) >= 4 && segs[1] == "documents" && segs[3] == "crdt" {
		return false
	}
	if len(segs) < 4 || segs[1] != "documents" || segs[3] != "changes" {
		return false
	}
	// Keyword position reached. The collection is exactly
	// {sessionId}/documents/{documentId}/changes; the subscribe subresource
	// adds one trailing "subscribe" segment and keeps its own guard. Anything
	// else past the keyword is a malformed 400.
	collection := len(segs) == 4 && segs[0] != "" && segs[2] != ""
	subscribe := len(segs) == 5 && segs[4] == "subscribe"
	return !(collection || subscribe)
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"time"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// subscribePageLimit is the page size used while replaying changes already
// committed after the subscription cursor. It matches the largest page the
// paginated read endpoint accepts, so catch-up and reads stay page-aligned.
const subscribePageLimit = 1000

// wsCloseEchoWait bounds how long a server-initiated close waits for the
// client's close echo before the deferred TCP teardown.
const wsCloseEchoWait = 500 * time.Millisecond

// handleSubscribe is the WebSocket document subscription mounted under the
// session view:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe?cursor=N
//
// The subscription identity is entirely the existing session: the session's
// owning device is the only credential. Validation happens entirely before
// the 101 handshake and writes nothing:
//
//  1. cursor must be a non-negative decimal integer (400 JSON otherwise),
//  2. the request must carry a valid WebSocket upgrade handshake (400 JSON),
//  3. the session must currently exist (404 JSON),
//  4. its device must currently hold permission for the document (403 JSON).
//
// After the upgrade the server first sends every committed change with a
// cursor greater than the starting cursor — paged in cursor order, one text
// frame per record in the exact {"id","deviceId","payload","cursor"} shape of
// a paginated read row — then seamlessly continues with changes committed by
// any write path (batch post, merge, restore, replay). Frames are never
// reordered or coalesced; a later read from the last observed cursor returns
// the same rows. The connection is push-only: inbound data frames are read
// and discarded, only close/ping control frames are honored.
//
// A permission revoked after the upgrade ends the subscription with close
// code 4403 and no further frame follows; a termination signal ends every
// subscription with 1001. A client disconnect simply unregisters — like long
// polling, a subscription writes no change, cursor or other record.
func handleSubscribe(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// Parameter shape first: a bad cursor is a 400 even when the session or
	// handshake is also bad, matching the session-scoped read ordering.
	cursor, ok := parseSubscribeCursor(w, r)
	if !ok {
		return
	}
	if !checkWebSocketUpgrade(r) {
		writeError(w, http.StatusBadRequest, "a WebSocket upgrade handshake is required")
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}
	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	conn, err := upgradeWebSocket(w, r)
	if err != nil {
		// The 101 response could not be written and the connection has been
		// hijacked (or is gone), so no JSON error can be produced. Nothing
		// was registered or written to the store.
		return
	}

	serveSubscription(r, s, conn, documentID, deviceID, cursor)
}

// parseSubscribeCursor validates the mandatory cursor query parameter: it
// must be present and a decimal non-negative integer. Negative, fractional
// and non-numeric values are a 400 JSON error; signs and adornments are
// rejected.
func parseSubscribeCursor(w http.ResponseWriter, r *http.Request) (int64, bool) {
	raw := r.URL.Query().Get("cursor")
	// parseCursorPath accepts only decimal digits (no sign, fraction or
	// exponent); a missing parameter is an empty raw and is rejected too.
	cursor, ok := parseCursorPath(raw)
	if !ok {
		writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
		return 0, false
	}
	return cursor, true
}

// serveSubscription runs one upgraded connection to completion. It registers
// before the first log read (a commit landing during catch-up is therefore
// never missed), then alternates a flush phase — drain every page of changes
// past the last sent cursor — and a park phase on the wake channel. A revoke
// is acted on only after the committed tail is flushed, so a commit that was
// authorized when it landed is still delivered ahead of the 4403. The method
// returns when the client leaves, permission is revoked or the store starts
// closing; the hijacked connection is closed on exit.
func serveSubscription(r *http.Request, s *app.App, conn *wsConn, documentID, deviceID string, cursor int64) {
	// Registration precedes the first read: the wake channel is buffered, so
	// a commit during a read leaves a pending wake that makes the next park
	// return immediately — no wake is lost. The revoked channel closes once
	// if access is withdrawn, and that event survives a racing re-grant.
	wakeCh, revokedCh, unregister := s.AddSubscription(documentID, deviceID)
	defer func() {
		unregister()
		_ = conn.NetClose()
	}()

	clientGone := make(chan struct{})
	go func() {
		defer close(clientGone)
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				// A malformed frame ends the connection with the RFC
				// protocol-error code; a client close is already echoed
				// inside ReadMessage; a network drop needs no frame.
				var protoErr *wsProtocolErrorString
				if errors.As(err, &protoErr) {
					_ = conn.Close(wsCloseProtocolError, "protocol error")
				}
				return
			}
			// Push-only channel: an inbound data frame is read and
			// discarded; the client cannot mutate the log over it.
		}
	}()

	// checkEnd non-blockingly maps a closing store to 1001 and a sticky
	// revoke to 4403; it returns true when the subscription must end. A
	// termination signal takes precedence: SIGTERM must end every
	// subscription with 1001 even if a revoke is also pending.
	checkEnd := func() bool {
		if s.Closing() {
			endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
			return true
		}
		select {
		case <-revokedCh:
			endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
			return true
		default:
		}
		return false
	}

	position := cursor
	first := true
	for {
		if !first {
			// Park until a commit, a sticky revoke or the termination signal
			// wakes us. r.Context() covers a non-shutdown cancel; the read
			// pump covers a client disconnect.
			select {
			case <-wakeCh:
				// Drain any coalesced follow-up signal as well; the flush
				// below reconciles every case by re-reading from the last
				// sent cursor.
				select {
				case <-wakeCh:
				default:
				}
			case <-revokedCh:
				if s.Closing() {
					endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
					return
				}
				endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
				return
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			}
			if s.Closing() {
				endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
				return
			}
		}
		first = false

		// Flush phase: page every change past position in cursor order. A
		// termination signal or a revoke is honored between pages/rows so a
		// large catch-up cannot delay the closing frame. A revoke arriving
		// while the final already-authorized tail is in flight is checked
		// after the inner loop, so that tail still goes out first.
		for {
			if checkEnd() {
				return
			}
			select {
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			default:
			}

			changes, _, err := s.ListChanges(documentID, position, subscribePageLimit)
			if err != nil {
				_ = conn.Close(wsCloseInternalError, "internal error")
				return
			}
			for i := range changes {
				if checkEnd() {
					return
				}
				raw, marshalErr := json.Marshal(changes[i])
				if marshalErr != nil {
					_ = conn.Close(wsCloseInternalError, "internal error")
					return
				}
				if writeErr := conn.WriteText(raw); writeErr != nil {
					return
				}
				position = changes[i].Cursor
			}
			if len(changes) < subscribePageLimit {
				break
			}
		}

		// Caught up. A revoke that arrived during the last page (its tail was
		// just flushed) now ends the subscription; otherwise loop and park.
		// Closing still wins over a pending revoke.
		if checkEnd() {
			return
		}
	}
}

// endSubscription sends the mandated closing frame and briefly waits for the
// read pump to observe the peer's close echo, so a graceful close reaches the
// client instead of being truncated by the deferred TCP teardown. It returns
// promptly if the peer is already gone; the caller's deferred NetClose drops
// the socket either way.
func endSubscription(conn *wsConn, clientGone <-chan struct{}, code int, reason string) {
	_ = conn.Close(code, reason)
	timer := time.NewTimer(wsCloseEchoWait)
	defer timer.Stop()
	select {
	case <-clientGone:
	case <-timer.C:
	}
}

