510		// Seed a second object {"b":2} at cursor 2.
511		w, _ = postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
512			"deviceId": "dev",
513			"changes":  []any{map[string]any{"id": "c2", "payload": map[string]any{"b": 2}}},
514		})
515		if w.Code != 200 {
